#!/usr/bin/env python3
from pathlib import Path
import base64, hashlib, subprocess, zlib

PATCH = ''
EXPECTED = {'.github/workflows/sol281-targeted.yml': 'fc6eb785b91c6b5e002409c03da90c86b94f8b8b7f3a9380d23d19004fd5a29b', 'godot/scripts/solid_detachment_lab.gd': 'b49f74326386bcd4e0e6fad177befb1df003ee8d1ca1580f30c1396125cc9fc0', 'godot/scripts/solid_detachment_session.gd': '9924ba7e81f902303a06eeb87a12a56140c83c2e60553b8fd894a0c7d2d11668', 'godot/scripts/solid_detachment_worker.gd': 'b5718ab9958b28587b33cee4851be4527004f1b2e9a15ffb680b5040f46fcd9b', 'godot/tests/test_solid_detachment_coupling.gd': '45ca2b3bdd76406bf42060709e10fa3f4b2604d0162936a0eebe689497ba4abd'}
patch = zlib.decompress(base64.b64decode(PATCH))
subprocess.run(["git", "apply", "--binary", "--whitespace=error-all", "-"], input=patch, check=True)
for path, expected in EXPECTED.items():
    actual = hashlib.sha256(Path(path).read_bytes()).hexdigest()
    if actual != expected:
        raise SystemExit(f"materialized hash mismatch: {path} {actual} != {expected}")
print("materialized SOL281 compound coupling", len(patch), "patch bytes")
